diff --git a/src/shared/content-r35.css b/src/shared/content-r35.css
index bbd02e5..7a72cf2 100644
--- a/src/shared/content-r35.css
+++ b/src/shared/content-r35.css
@@ -1,4 +1,7 @@
 /* Current round: cues are projections of the same playable state. */
+/* R36: do not paint a road or lane markings before that side is observed. */
+#content-r1[data-kind=crossing] .r32-road-thumb[data-observed=false]{background:#dce4e8!important}
+#content-r1[data-kind=crossing] .r32-road-thumb[data-observed=false]::after{display:none!important}
 #content-r1[data-kind=cake] .r33-tray::before,#content-r1[data-kind=cake] .r33-tray::after{content:'';position:absolute;top:-7px;width:20px;height:20px;border:5px solid transparent;border-radius:50%;box-sizing:border-box}
 #content-r1 .r33-tray::before{left:-9px}#content-r1 .r33-tray::after{right:-9px}
 #content-r1[data-kind=cake] .r33-tray[data-warning=left]::before,#content-r1[data-kind=cake] .r33-tray[data-warning=right]::after{border-color:#d54a32;background:#ffd344;box-shadow:0 0 0 4px #fff8d9}

diff --git a/src/shared/content-r31-scene.js b/src/shared/content-r31-scene.js
index 56fc03f..787a1e1 100644
--- a/src/shared/content-r31-scene.js
+++ b/src/shared/content-r31-scene.js
@@ -19,8 +19,10 @@ export function cakeView(g){
 }
 export function crossingView(g){
  const active=g.trafficActive,side=g.trafficSource,stale=g.staleSide;
- const sides=Object.fromEntries(['left','right'].map(s=>{const car=active&&side===s,confirmed=!!g.looked[s]&&!car&&stale!==s;
-  return [s,Object.freeze({car,confirmed,stale:stale===s,road:car?(g.newTraffic&&g.crossTime>0?'車在線前等':'有車通過'):'路面淨空',check:car?'等車過':stale===s?'↻ 要重看':confirmed?'✓ 我看過了':'○ 還沒看'})];}));
+ const sides=Object.fromEntries(['left','right'].map(s=>{const observed=!!(g.looked[s]||g.viewVisit?.[s]),car=observed&&active&&side===s,confirmed=!!g.looked[s]&&!car&&stale!==s;
+  // The scene may contain traffic; an unvisited thumbnail knows only that
+  // the child has not looked. All later projections retain this boundary.
+  return [s,Object.freeze({observed,car,confirmed,stale:stale===s,road:!observed?'還沒看':car?(g.newTraffic&&g.crossTime>0?'車在線前等':'有車通過'):'路面淨空',check:!observed?'○ 還沒看':car?'等車過':stale===s?'↻ 要重看':confirmed?'✓ 我看過了':'○ 還沒看'})];}));
  let id='waiting',action='',text='看清楚了，讓朋友先過。';
  if(g.phase==='departing'){id='departing';text='路面淨空，慢慢出發。';}
  else if(g.speed>.05){id='stopping';action='brake';text='按住煞車，停在線前。';}

diff --git a/src/shared/content-r32-scene.js b/src/shared/content-r32-scene.js
index 87e3a7a..ae20e6d 100644
--- a/src/shared/content-r32-scene.js
+++ b/src/shared/content-r32-scene.js
@@ -32,7 +32,7 @@ export function crossingView(g){
  const t=clamp(time/total),travel=yielding?clamp(time/.3)*.16:clamp((t-.09)/.91)*.84+.16;
  const x=side==='left'?4+92*travel:96-92*travel;
  const traffic=Object.freeze({...old.traffic,x,top:CROSSING_ROADS[g.stage].center-5,yielding,motion:yielding?'讓行':t<.28?'接近':t>.78?'離開':'通過'});
- const sides=Object.freeze(Object.fromEntries(Object.entries(old.sides).map(([s,v])=>[s,Object.freeze({...v,road:v.car?(yielding?'車停在線前':'車正在'+traffic.motion):'路面淨空'})])));
+ const sides=Object.freeze(Object.fromEntries(Object.entries(old.sides).map(([s,v])=>[s,Object.freeze({...v,road:!v.observed?v.road:v.car?(yielding?'車停在線前':'車正在'+traffic.motion):'路面淨空'})])));
  let text=old.text;
  if(yielding)text='車在線前等，朋友先過。';
  if(g.practice&&g.safetyNotice>0&&g.choiceHint)text=g.choiceHint;
